script.source:
#!/bin/bash set -euxo pipefail echo "=== AutoYaST: Invoking CSIR Appliance Online Remote Bootstrap ==="
# AutoYaST mounts the newly installed target system at /mnt TARGET="/mnt"
# Fetch and execute the online bootstrap directly onto the mounted target BOOTSTRAP_URL="https://raw.githubusercontent.com/ananthkrishnangv/CSIR-SERC-Web-Appliance-OS/main/installer/install.sh" curl -sSL --retry 3 "$BOOTSTRAP_URL" | chroot "$TARGET" bash -s -- --unattended --all || true
